","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"YONTEF, G. M.","work":"Processo, diálogo e awareness: ensaios em Gestalt-terapia","year":1998,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"chegada-1","kind":"guidance","title":"Chegar ao momento presente","text":"A chegada é um convite para perceber como você está antes de começar algo. Não há resposta certa: notar o que aparece já é o exercício."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"PERLS, L.","work":"Living at the boundary","year":1992,"edition":"Highland: The Gestalt Journal Press","pages":""}],"asset":"","license":"","id":"chegada-2","kind":"guidance","title":"Tudo é opcional","text":"Você pode pular qualquer etapa. Escolher não responder também é uma forma de cuidar do próprio ritmo."}],"audio":[],"artApprovalId":null},"mapa-do-corpo":{"schemaVersion":1,"resourceKey":"mapa-do-corpo","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"MERLEAU-PONTY, M.","work":"Fenomenologia da percepção","year":1999,"edition":"São Paulo: Martins Fontes","pages":""},{"author":"POLSTER, E.; POLSTER, M.","work":"Gestalt-terapia integrada","year":2001,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"corpo-1","kind":"guidance","title":"Perceber sem interpretar","text":"Localize sensações no corpo sem procurar explicações. Tensão, calor, peso ou ausência de percepção são informações igualmente válidas."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"PERLS, L.","work":"Living at the boundary","year":1992,"edition":"Highland: The Gestalt Journal Press","pages":""}],"asset":"","license":"","id":"corpo-2","kind":"guidance","title":"Percorrer com gentileza","text":"No modo percorrer, passe por cada região no seu tempo. Se uma região pedir mais atenção, permaneça; se incomodar, siga adiante."}],"audio":[],"artApprovalId":null},"polaridades-e-cadeiras":{"schemaVersion":1,"resourceKey":"polaridades-e-cadeiras","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"POLSTER, E.; POLSTER, M.","work":"Gestalt-terapia integrada","year":2001,"edition":"São Paulo: Summus","pages":""},{"author":"ZINKER, J.","work":"Processo criativo em Gestalt-terapia","year":2007,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"polaridades-1","kind":"guidance","title":"Dois lados de uma experiência","text":"Polaridades são forças que coexistem na pessoa, como querer e não querer. O exercício é dar voz a cada lado, não escolher o vencedor."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"ZINKER, J.","work":"Processo criativo em Gestalt-terapia","year":2007,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"polaridades-2","kind":"guidance","title":"Escrita, não terapia","text":"Este é um experimento de escrita para a formação. A cadeira vazia em processo terapêutico requer condução profissional."}],"audio":[],"artApprovalId":null},"paisagem-de-pensamentos":{"schemaVersion":1,"resourceKey":"paisagem-de-pensamentos","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"YONTEF, G. M.","work":"Processo, diálogo e awareness: ensaios em Gestalt-terapia","year":1998,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"paisagem-1","kind":"guidance","title":"Pensar também acontece agora","text":"Pensamentos podem ser observados como acontecimentos do momento, como nuvens ou folhas na correnteza, sem precisar resolvê-los."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[],"asset":"","license":"","id":"paisagem-2","kind":"guidance","title":"Jardim e rio","text":"No jardim, você pousa escritas para revisitar. No rio, elas passam e não ficam guardadas."}],"audio":[],"artApprovalId":null},"sons-para-awareness":{"schemaVersion":1,"resourceKey":"sons-para-awareness","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"POLSTER, E.; POLSTER, M.","work":"Gestalt-terapia integrada","year":2001,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"sons-1","kind":"guidance","title":"Escutar o entorno","text":"Feche os olhos se for confortável e perceba os sons ao redor: perto, longe, contínuos, intermitentes. Nomeie sem julgar."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[],"asset":"","license":"","id":"sons-2","kind":"guidance","title":"Sem áudio também funciona","text":"As gravações do Instituto serão incluídas quando houver arquivos licenciados. Até lá, os sons do seu lugar são a matéria da experiência."}],"audio":[],"artApprovalId":null},"sala-de-pausa":{"schemaVersion":1,"resourceKey":"sala-de-pausa","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[{"author":"YONTEF, G. M.","work":"Processo, diálogo e awareness: ensaios em Gestalt-terapia","year":1998,"edition":"São Paulo: Summus","pages":""}],"asset":"","license":"","id":"pausa-1","kind":"guidance","title":"Uma pausa que caiba","text":"Escolha uma prática breve que faça sentido agora. A pausa não tem meta de tempo nem de resultado."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[],"asset":"","license":"","id":"pausa-2","kind":"guidance","title":"Interromper também é cuidado","text":"Você pode trocar de prática ou encerrar quando quiser."}],"audio":[],"artApprovalId":null},"igarape":{"schemaVersion":1,"resourceKey":"igarape","items":[{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[],"asset":"","license":"","id":"igarape-1","kind":"guidance","title":"Acompanhar a água","text":"Toque a superfície e acompanhe as ondulações até se acalmarem. Perceba como o seu ritmo acompanha o da água."},{"deck":"","format":"","prompt":"","teacherResponse":"","segments":[],"alternatives":[],"relatedConcepts":[],"references":[],"asset":"","license":"","id":"igarape-2","kind":"guidance","title":"Versão estática","text":"Se o movimento incomodar, escolha a versão estática: a experiência continua disponível sem animação."}],"audio":[],"artApprovalId":null}}$conteudo$::jsonb;
 chave text; configuracao jsonb; administrador uuid; proxima integer; publicados integer := 0; preservados text[] := array[]::text[];
begin
 if not exists(select 1 from information_schema.columns where table_schema='public' and table_name='resource_content_versions' and column_name='demo') then
  raise exception 'Aplique antes supabase/migrations/20261013110000_recursos_modo_demonstracao.sql.';
 end if;
 select id into administrador from public.profiles where role='admin' and is_active order by id limit 1;
 if administrador is null then raise exception 'Nenhuma conta de administração ativa encontrada.'; end if;
 for chave, configuracao in select key, value from jsonb_each(conteudo) loop
  -- Uma versão assinada por docente nunca é substituída por demonstração.
  if exists(select 1 from public.resource_content_versions where resource_key=chave::public.fv_resource_key and status='published' and not demo) then
   preservados := array_append(preservados, chave); continue;
  end if;
  delete from public.resource_content_versions where resource_key=chave::public.fv_resource_key and status='draft' and jsonb_array_length(configuration->'items')=0;
  update public.resource_content_versions set status='archived' where resource_key=chave::public.fv_resource_key and status='published' and demo;
  select coalesce(max(version),0)+1 into proxima from public.resource_content_versions where resource_key=chave::public.fv_resource_key;
  insert into public.resource_content_versions(resource_key,version,status,demo,configuration,authored_by)
   values(chave::public.fv_resource_key,proxima,'published',true,configuracao,administrador);
  publicados := publicados+1;
 end loop;
 raise notice 'Recursos publicados como demonstração: %. Preservados por terem versão assinada: %.', publicados, coalesce(array_to_string(preservados, ', '), 'nenhum');
end $seed$;
commit;
